import {accounts,AS_OF,signals,metrics,quality,growth,percent,money,shortMoney,brief,filtered,probabilities,accountCSV} from './model.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#detail');
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',queue:'M4 6h16 M4 12h16 M4 18h16',accounts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 8a3 3 0 0 1 0 6 M22 21v-2a4 4 0 0 0-3-4',renewals:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18',pipeline:'M3 18h4V9H3z M10 18h4V3h-4z M17 18h4v-6h-4z',quality:'M12 3 2 21h20L12 3z M12 9v5 M12 17v1',method:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',arrow:'M5 12h14 M14 7l5 5-5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.overview}"/></svg>`;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='revenue-signal-lab-v1';let saved={};try{const value=JSON.parse(localStorage.getItem(key)||'{}');if(value&&typeof value==='object'&&!Array.isArray(value))saved=value}catch{}
let view=location.hash.slice(1)||'overview',filters={query:'',segment:'All segments',motion:'All motions',owner:'All owners'},selected=null;
const navs=[['overview','Overview'],['queue','Action queue'],['accounts','Accounts'],['renewals','Renewals'],['pipeline','Pipeline'],['quality','Data quality'],['method','Method & sources']];
function badge(v){return `<span class="badge ${v.toLowerCase().replaceAll(' ','-')}">${escape(v)}</span>`}
function toast(v){const el=document.querySelector('#toast');el.textContent=v;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));return true}catch{toast('Browser storage unavailable. Changes remain in this session only.');return false}}
const initial=a=>a.name.split(' ').map(n=>n[0]).slice(0,2).join('');
function accountLink(a){return `<button class="account" data-account="${a.id}"><span class="initial">${initial(a)}</span><span><strong>${a.name}</strong><small>${a.industry} · ${a.segment}</small></span></button>`}
function metric(title,value,foot){return `<div class="metric"><label>${title}</label><strong>${value}</strong><small>${foot}</small></div>`}
function chart(){const totals=Array.from({length:6},(_,i)=>accounts.reduce((s,a)=>s+a.months[i],0));const max=Math.max(...totals)*1.08,min=Math.min(...totals)*.85;const points=totals.map((n,i)=>`${48+i*96},${155-(n-min)/(max-min)*135}`).join(' ');return `<div class="chart"><svg viewBox="0 0 550 180" role="img" aria-label="Synthetic verification volumes in six consecutive 30-day periods: ${totals.map(n=>n.toLocaleString()).join(', ')}"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#bad69e" stop-opacity=".6"/><stop offset="1" stop-color="#bad69e" stop-opacity=".02"/></linearGradient></defs>${[35,90,145].map((y,i)=>`<line x1="48" x2="530" y1="${y}" y2="${y}" stroke="#e9eee7" stroke-dasharray="3 4"/><text x="0" y="${y+4}" fill="#85917f" font-size="11">${((max-(max-min)*((y-20)/135))/1e6).toFixed(1)}m</text>`).join('')}<polygon points="48,170 ${points} 528,170" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#548355" stroke-width="2.5"/>${points.split(' ').map(p=>{const [x,y]=p.split(',');return `<circle cx="${x}" cy="${y}" r="4" fill="#fff" stroke="#548355" stroke-width="2"/>`}).join('')}</svg><div class="chart-labels">${['Apr','May','Jun','Jul','Aug','Sep'].map(m=>`<span>${m}</span>`).join('')}</div><div class="chart-caption"><span><i class="legend"></i>Portfolio verification volume</span><span>30-day buckets · includes stale feeds</span></div></div>`}
function table(rows,limit=99){return `<div class="table-wrap"><table><thead><tr><th>Account</th><th>Motion / evidence</th><th>Priority</th><th>Contract ARR</th><th>Usage Δ</th><th>Owner</th><th></th></tr></thead><tbody>${rows.slice(0,limit).map(a=>{const s=signals(a);return `<tr><td>${accountLink(a)}</td><td>${badge(s.motion)}<div class="reason">${s.reasons[0]}</div></td><td><span class="score">${s.score} <small>/ 100</small></span><div class="scorebar"><i style="width:${s.score}%"></i></div></td><td>${shortMoney(a.arr)}</td><td class="${growth(a)>=0?'up':'down'}">${percent(growth(a))}${a.usageAgeDays>7?' †':''}</td><td><small>${s.role}</small><br>${s.owner}</td><td><button class="text-btn" data-account="${a.id}" aria-label="Open ${a.name}">↗</button></td></tr>`}).join('')}</tbody></table>${!rows.length?'<div class="empty">No accounts match these filters. Try another search or clear filters.</div>':''}</div>`}
function filterBar(){return `<div class="filters"><input id="search" aria-label="Search accounts" placeholder="Search accounts…" value="${escape(filters.query)}">${[['segment',['All segments','Enterprise','Mid-market','Growth']],['motion',['All motions','Expansion','Retention','Data quality','Monitor']],['owner',['All owners','Alex Chen','Priya Shah','Jordan Lee','Sam Rivera','Tejas Singh']]].map(([id,options])=>`<select id="${id}" aria-label="Filter by ${id}">${options.map(o=>`<option ${filters[id]===o?'selected':''}>${o}</option>`).join('')}</select>`).join('')}<button class="text-btn" data-clear>Clear</button></div>`}
function overview(){const m=metrics(accounts),queue=filtered(accounts).filter(a=>signals(a).motion!=='Monitor'),ren=[...accounts].filter(a=>a.renewalDays<=90).sort((a,b)=>a.renewalDays-b.renewalDays);return `<div class="summary-band"><div><h2>A clearer view. A more focused week.</h2><p>${queue.length} accounts need attention. Protect near-term renewals, then qualify credible expansion.</p></div><div class="band-tag"><span>↗</span><b>${m.expansion} expansion signals</b></div></div><div class="metrics">${metric('Portfolio ARR',shortMoney(m.arr),'24 accounts · annual contract value')}${metric('Renewing in 90 days',shortMoney(m.renewal),`${ren.length} contracts · not a revenue forecast`)}${metric('Retention attention',shortMoney(m.risk),'ARR on accounts routed to retention')}${metric('Weighted pipeline',shortMoney(m.pipeline),'Open opportunity value × stage weight')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Customer activity</h2><p>Verification demand across the portfolio</p></div><span class="badge">6 months</span></div>${chart()}</section><section class="panel"><div class="panel-head"><div><h2>Renewals on the horizon</h2><p>Next 90 days · ordered by renewal date</p></div><button class="text-btn" data-nav="renewals">View all ↗</button></div>${ren.slice(0,3).map(a=>`<div class="renewal-row"><div><button data-account="${a.id}">${a.name}</button><small>${a.csm} · ${shortMoney(a.arr)} ARR</small></div><div>${badge(a.renewalDays+' days')}<small>${a.renewalStatus}</small></div></div>`).join('')}</section></div><section class="panel"><div class="panel-head"><div><h2>This week’s priorities <span class="count">${queue.length}</span></h2><p>Explainable signals, a named owner and a practical next step.</p></div><button class="text-btn" data-nav="queue">Open action queue ↗</button></div>${table(queue,5)}<div class="page-count">Top 5 by rule priority, then ARR · ${m.quality} accounts require data validation</div></section>`}
function accountPage(){const rows=filtered(accounts,filters);return `<div class="segment-grid" style="margin-bottom:24px">${['Enterprise','Mid-market','Growth'].map(s=>{const r=accounts.filter(a=>a.segment===s),m=metrics(r);return `<div class="panel segment-card"><h3>${s}</h3><strong>${shortMoney(m.arr)}</strong><small>${r.length} accounts · ${m.expansion} expansion signals</small><div class="progress"><i style="width:${m.arr/metrics(accounts).arr*100}%"></i></div><button class="text-btn" data-segment="${s}">Explore segment ↗</button></div>`}).join('')}</div><section class="panel"><div class="panel-head"><h2>Account portfolio</h2><span class="count" id="account-count">${rows.length} accounts</span></div>${filterBar()}<div id="results">${table(rows)}</div></section>`}
function workflowRows(){return filtered(accounts,{...filters,owner:'All owners'}).filter(a=>filters.owner==='All owners'||(saved[a.id]?.owner||signals(a).owner)===filters.owner)}
function queuePage(){const rows=workflowRows().filter(a=>signals(a).motion!=='Monitor');return `<section class="panel"><div class="panel-head"><div><h2>From signal to action</h2><p>Assignments and progress are saved only in this browser. No CRM messages are sent.</p></div><button class="text-btn" id="reset">Reset demo</button></div>${filterBar()}<div id="results">${tasks(rows)}</div></section>`}
function tasks(rows){return rows.length?rows.map(a=>{const s=signals(a),state=saved[a.id]||{};return `<article class="task-card"><div><div class="toolbar">${badge(s.motion)}${badge(s.priority+' priority')}<small>${s.score}/100</small></div><button class="text-btn" style="padding:12px 0 0" data-account="${a.id}">${a.name} ↗</button><p>${s.action}.</p><small>${s.reasons.join(' · ')}</small><small style="margin-top:8px">Target: within ${s.due} business days of review · ${shortMoney(a.arr)} ARR</small></div><div><label for="owner-${a.id}">Action owner</label><select class="status-select" id="owner-${a.id}" data-owner="${a.id}">${['Alex Chen','Priya Shah','Jordan Lee','Sam Rivera','Tejas Singh'].map(o=>`<option ${(state.owner||s.owner)===o?'selected':''}>${o}</option>`).join('')}</select><label for="status-${a.id}">Progress</label><select class="status-select" id="status-${a.id}" data-status="${a.id}">${['To do','In progress','Done'].map(o=>`<option ${(state.status||'To do')===o?'selected':''}>${o}</option>`).join('')}</select></div></article>`}).join(''):'<div class="empty">No actionable accounts match these filters.</div>'}
function renewals(){const rows=accounts.filter(a=>a.renewalDays<=90).sort((a,b)=>a.renewalDays-b.renewalDays);return `<div class="metrics">${[30,60,90].map((d,i)=>metric(`${i*30+1}–${d} days`,shortMoney(rows.filter(a=>a.renewalDays>i*30&&a.renewalDays<=d).reduce((s,a)=>s+a.arr,0)),'Annual contract value in renewal window')).join('')}${metric('Total renewal exposure',shortMoney(metrics(accounts).renewal),'Next 90 days · USD')}</div><section class="panel"><div class="panel-head"><h2>Renewal planning</h2><span class="badge">Snapshot · 22 Sep 2026</span></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Due in</th><th>ARR</th><th>Commercial status</th><th>Routing</th><th>CSM</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${accountLink(a)}</td><td>${a.renewalDays} days</td><td>${money(a.arr)}</td><td>${badge(a.renewalStatus)}</td><td>${badge(signals(a).motion)}</td><td>${a.csm}</td></tr>`).join('')}</tbody></table></div></section>`}
function pipeline(){return `<div class="summary-band"><div><h2>${shortMoney(metrics(accounts).pipeline)} weighted pipeline</h2><p>Illustrative expansion opportunities already in CRM. Signal candidates are not automatically counted as pipeline.</p></div></div><div class="pipeline">${Object.entries(probabilities).filter(([s])=>s!=='None').map(([stage,p])=>{const rows=accounts.filter(a=>a.stage===stage);return `<section class="stage-col"><h3>${stage} <span class="count">${rows.length}</span></h3><small>${p*100}% stage weight · ${shortMoney(rows.reduce((s,a)=>s+a.opportunity,0))} unweighted</small><div style="margin-top:18px">${rows.map(a=>`<div class="deal"><button data-account="${a.id}">${a.name} ↗</button><strong>${money(a.opportunity)}</strong><small>Owner: ${a.ae}<br>Expected close: ${a.closeDays} days<br>Weighted: ${money(a.opportunity*p)}</small><div style="margin-top:10px">${badge(signals(a).motion)}</div></div>`).join('')}</div></section>`}).join('')}</div>`}
function qualityPage(){const rows=accounts.filter(a=>quality(a).length);return `<div class="summary-band"><div><h2>Trust the inputs before acting on the signal.</h2><p>${rows.length} accounts have stale or missing inputs. Commercial recommendations are held until validation.</p></div><span class="badge">RevOps owns triage</span></div><div class="metrics">${metric('CRM freshness','≤14 days','Demo acceptance threshold')}${metric('Usage freshness','≤7 days','Demo acceptance threshold')}${metric('Affected accounts',rows.length,'Account counts, not issue counts')}${metric('Affected ARR',shortMoney(rows.reduce((s,a)=>s+a.arr,0)),'Included in portfolio; excluded from expansion')}</div><section class="panel"><div class="panel-head"><h2>Exceptions to resolve</h2></div>${table(rows)}</section>`}
function method(){return `<section class="panel method"><h2>A revenue workflow, with evidence attached.</h2><p>Revenue Signal Lab is an independent portfolio by Tejas Singh. Every account, owner, contract, opportunity and operational metric is fictional. It is inspired by public identity-verification use cases, not commissioned by or affiliated with Trulioo. No internal data, internal logic or performance claims are used.</p><h2>How prioritization works</h2><p>One account gets one primary motion. The rules below run in order. They are explicit portfolio assumptions that a real RevOps team would validate and calibrate.</p><table><thead><tr><th>Order / motion</th><th>Trigger</th><th>Priority points</th></tr></thead><tbody><tr><td>1 · Data quality</td><td>Usage older than 7 days, CRM older than 14 days, missing owner or invalid baseline</td><td>75</td></tr><tr><td>2 · Retention</td><td>Success rate falls ≥5 percentage points; ≥10 open tickets; volume falls ≥15%; or renewal ≤45 days</td><td>40 base +25 friction +20 decline +15 near renewal; cap 100</td></tr><tr><td>3 · Expansion</td><td>Volume grows ≥20%, ≥1 new market and eligible product whitespace, after preceding gates pass</td><td>40 + rounded growth×50 + new markets×5 +10 if ARR ≥$300k; cap 90</td></tr><tr><td>4 · Monitor</td><td>No earlier rule applies</td><td>20</td></tr></tbody></table><p>High priority: ≥80. Medium: 50–79. Low: &lt;50. Queue order is points descending, then ARR descending. A score is a workload-ordering aid, never a churn or conversion probability. A renewal alone can trigger a medium-priority commercial review; it does not prove distress.</p><h2>Metric definitions</h2><p>ARR is annualized contracted recurring value in USD, not recognized revenue or usage-based billing. Retention attention sums ARR for accounts currently routed to retention, not expected losses. Renewal exposure sums ARR renewing in the next 90 days, inclusive. Usage change compares the current 90-day total to the prior 90-day total. The activity chart uses six consecutive 30-day buckets ending on the snapshot date; month labels are approximate. The first three reconcile to prior 90-day volume and the last three to current 90-day volume (rounding within two checks). Success-rate differences are percentage points. Pipeline uses synthetic stage weights: Discovery 20%, Qualification 35%, Proposal 60%, Negotiation 80%. These are scenario weights, not a calibrated forecast.</p><h2>AI account brief: bounded by the evidence</h2><p>The brief is a deterministic, template-based preview of an AI-assisted workflow. It uses the same structured signals shown in each account. No language model is called, no data leaves the browser, and no external knowledge or invented customer narrative is added. This intentionally avoids pretending that generated text or synthetic data validates an ML model. It is fully functional as an evidence-linked account summary.</p><p>A future LLM adapter should receive only these validated fields, return a strict schema with evidence IDs, and reject unsupported assertions. Human approval must remain between a recommendation and outreach. A production integration would also need authentication, shared storage, audit controls and monitored source pipelines.</p><h2>Sources & boundaries</h2><p>Public product context checked 22 September 2026: <a href="https://www.trulioo.com/solutions" target="_blank" rel="noreferrer">Trulioo solutions</a>, <a href="https://www.trulioo.com/industries/marketplaces-identity-verification" target="_blank" rel="noreferrer">marketplace verification</a>, and <a href="https://www.trulioo.com/identity-verification-use-cases/global-expansion" target="_blank" rel="noreferrer">global expansion</a>. These support the choice of verification, market and product-adoption signals only. Product eligibility, pricing, stage weights and account-health thresholds are authored assumptions.</p><h2>Demo boundaries</h2><p>24 fixed synthetic accounts as of 22 September 2026. Filters are session state. Assignments, workflow status and notes are stored locally in this browser; reset clears them. No real CRM, shared database, customer outreach, customer-level personal information or live AI provider is connected. Stale source values remain visible with warnings and are not silently treated as fresh. The local activity history records demo edits; it is not a tamper-proof audit log.</p></section>`}
const titles={overview:['Portfolio overview','Your revenue book, translated into the next best action.'],queue:['Action queue','A shared operating rhythm starts with clear ownership.'],accounts:['Account intelligence','Connect commercial context with customer behavior.'],renewals:['Renewal workspace','Make the next 90 days visible, owned and actionable.'],pipeline:['Expansion pipeline','Separate qualified commercial opportunities from early signals.'],quality:['Data quality','Surface the blind spots before they become decisions.'],method:['Method & sources','Transparent assumptions. Traceable evidence. Honest boundaries.']};
function render(){if(!titles[view])view='overview';const [title,sub]=titles[view];app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark"><i></i><i></i><i></i></span><span>Revenue<br>Signal Lab<span style="color:#b7e793">.</span></span></div><div class="workspace">Revenue workspace</div><nav class="nav" aria-label="Main navigation">${navs.map(([id,n])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(id)}${n}</button>`).join('')}</nav><div class="sidebottom"><strong>Signals → decisions → action</strong>A RevOps portfolio grounded in public identity-verification context.<div class="sideprofile"><span class="avatar">TS</span><div><strong>Tejas Singh</strong>Portfolio workspace</div></div></div></aside><div><header class="topbar"><span>Workspace <span style="color:#bcc7bf;margin:0 10px">/</span> ${navs.find(n=>n[0]===view)[1]}</span><div class="right"><span>22 Sep 2026 snapshot</span><span class="synthetic">Synthetic data</span><span class="avatar">TS</span></div></header><main class="main"><div class="heading"><div><div class="eyebrow">Revenue operations</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><button class="btn" id="export">${icon('download')} Export accounts</button></div>${({overview,accounts:accountPage,queue:queuePage,renewals,pipeline,quality:qualityPage,method})[view]()}<footer class="footnote">Independent portfolio by Tejas · All accounts and metrics are synthetic · USD · No Trulioo internal data or affiliation</footer></main></div></div>`;bind()}
function navigate(v){view=v;location.hash=v;filters={query:'',segment:'All segments',motion:'All motions',owner:'All owners'};render();window.scrollTo(0,0)}
function record(id,field,value){saved[id]={...saved[id],[field]:value,history:[...(saved[id]?.history||[]),{at:new Date().toISOString(),field,value}].slice(-20)};persist()}
function bind(){app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));bindAccounts(app);app.querySelectorAll('[data-segment]').forEach(b=>b.onclick=()=>{filters.segment=b.dataset.segment;render()});app.querySelector('[data-clear]')?.addEventListener('click',()=>{filters={query:'',segment:'All segments',motion:'All motions',owner:'All owners'};render()});['search','segment','motion','owner'].forEach(id=>{const el=app.querySelector('#'+id);el?.addEventListener(id==='search'?'input':'change',()=>{filters[id==='search'?'query':id]=el.value;const rows=view==='queue'?workflowRows():filtered(accounts,filters);app.querySelector('#results').innerHTML=view==='queue'?tasks(rows.filter(a=>signals(a).motion!=='Monitor')):table(rows);if(view==='accounts')app.querySelector('#account-count').textContent=rows.length+' accounts';bindAccounts(app);bindTasks()})});bindTasks();app.querySelector('#export').onclick=exportCSV;app.querySelector('#reset')?.addEventListener('click',()=>{showReset()})}
function bindAccounts(root){root.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>openAccount(b.dataset.account))}
function bindTasks(){app.querySelectorAll('[data-status]').forEach(el=>el.onchange=()=>{record(el.dataset.status,'status',el.value);toast('Progress saved in this browser')});app.querySelectorAll('[data-owner]').forEach(el=>el.onchange=()=>{record(el.dataset.owner,'owner',el.value);toast('Action owner updated in this browser');if(filters.owner!=='All owners')render()})}
const kv=(label,val)=>`<div class="kv"><span>${label}</span><b>${escape(val)}</b></div>`;
function openAccount(id){const a=accounts.find(x=>x.id===id);if(!a)throw new Error('Unknown account');selected=id;const s=signals(a),state=saved[id]||{};dialog.innerHTML=`<div class="dialog-top"><div><div class="eyebrow">${a.id} · ${a.segment} · ${a.region}</div><h2 id="detail-title">${a.name}</h2><small>${a.industry} · Synthetic account</small></div><button class="close" aria-label="Close account">×</button></div><div class="dialog-body"><div class="health-strip">${badge(s.motion)}${badge(s.priority+' priority')}<span class="badge">${s.score}/100 · rule priority</span>${badge('Usage feed: '+a.usageAgeDays+'d old')}</div><div class="detail-stat"><div><small>Contract ARR</small><strong>${shortMoney(a.arr)}</strong></div><div><small>90-day usage change</small><strong class="${growth(a)>=0?'up':'down'}">${percent(growth(a))}</strong></div><div><small>Renewal in</small><strong>${a.renewalDays} days</strong></div></div><div class="detail-box"><h3>Rules & routing</h3><ul>${s.reasons.map(r=>`<li>${r}</li>`).join('')}</ul><p><strong>Next action:</strong> ${s.action}.</p><p style="margin-top:8px"><strong>${escape(state.owner||s.owner)} · ${s.role}</strong> · Target within ${s.due} business days of review</p></div><div class="detail-grid"><div><section class="detail-box"><h3>Commercial context</h3>${kv('Account executive',a.ownerMissing?'Missing in CRM':a.ae)}${kv('Customer success',a.csm)}${kv('Last customer touch',a.lastTouchDays+' days ago')}${kv('CRM freshness',a.crmAgeDays+' days')}${kv('Renewal status',a.renewalStatus)}${kv('Opportunity stage',a.stage)}${kv('Opportunity value',money(a.opportunity))}${kv('Expected close',a.stage==='None'?'No open opportunity':a.closeDays+' days')}</section><section class="detail-box"><h3>Product adoption</h3>${a.eligible.map(p=>`<div class="product">${p}${badge(a.products.includes(p)?'Adopted':'Whitespace')}</div>`).join('')}<small>Eligibility is a synthetic assumption. Whitespace requires a product-fit conversation.</small></section></div><div><section class="detail-box"><h3>Usage & customer health</h3>${kv('Current 90-day volume',a.currentVolume.toLocaleString())}${kv('Prior 90-day volume',a.previousVolume.toLocaleString())}${kv('Current success rate',a.successCurrent+'%')}${kv('Prior success rate',a.successPrevious+'%')}${kv('Success-rate change',(a.successCurrent-a.successPrevious)+' pp')}${kv('Manual review rate',a.reviewRate+'%')}${kv('Open support tickets',a.tickets)}${kv('Active / new markets',a.countries+' / '+a.newCountries)}${s.quality.length?`<p style="margin-top:12px;color:#94642d">${s.quality.join('. ')}. Validate before outreach.</p>`:''}</section><section class="detail-box brief"><h3>✧ AI account brief</h3><p>A concise summary of this account’s displayed evidence.</p><small>Template-based demo · no live language model</small><button class="btn primary" style="margin-top:15px" id="generate">Generate evidence brief</button><div id="brief-output" aria-live="polite"></div></section></div></div><section class="detail-box"><h3>Workflow notes</h3><label for="note"><small>Keep the next conversation focused. Saved only in this browser.</small></label><textarea id="note" class="field note" maxlength="2000" placeholder="Add an observation or question for the account team…">${escape(state.note||'')}</textarea><div class="dialog-actions"><button id="save-note" class="btn primary">Save note</button><button id="start-action" class="btn">${state.status==='In progress'?'In progress':'Start action'}</button></div><div style="margin-top:16px" id="activity"><small>Local activity</small>${(state.history||[]).slice(-3).reverse().map(h=>`<p class="reason">${escape(h.at.slice(0,16).replace('T',' '))} · ${escape(h.field)} updated</p>`).join('')||'<p class="reason">No local changes yet.</p>'}</div></section></div>`;dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('#generate').onclick=()=>{const b=brief(a);dialog.querySelector('#brief-output').innerHTML=`<p>${b.summary}</p><p>${b.commercial}</p><p><strong>Recommended next step</strong><br>${escape(state.owner&&state.owner!==s.owner?b.action.replace(s.owner,state.owner):b.action)}</p><small>${b.caution}</small><p class="reason">Evidence: ${b.evidence.join(' · ')}</p>`;dialog.querySelector('#generate').textContent='Regenerate brief'};dialog.querySelector('#save-note').onclick=()=>{record(id,'note',dialog.querySelector('#note').value);updateActivity(id);toast('Note saved in this browser')};dialog.querySelector('#start-action').onclick=()=>{record(id,'status','In progress');dialog.querySelector('#start-action').textContent='In progress';updateActivity(id);toast('Action marked in progress');if(view==='queue')render()};if(!dialog.open)dialog.showModal()}
function updateActivity(id){dialog.querySelector('#activity').innerHTML='<small>Local activity</small>'+saved[id].history.slice(-3).reverse().map(h=>`<p class="reason">${escape(h.at.slice(0,16).replace('T',' '))} UTC · ${escape(h.field)} updated</p>`).join('')}
function showReset(){dialog.innerHTML=`<div class="dialog-top"><h2 id="detail-title">Reset this demo?</h2><button class="close" aria-label="Close reset">×</button></div><div class="dialog-body"><p>This clears assignments, notes and progress saved in this browser. The synthetic source accounts stay the same.</p><div class="dialog-actions" style="margin-top:20px"><button class="btn" id="cancel-reset">Keep my changes</button><button class="btn primary" id="confirm-reset">Reset local demo</button></div></div>`;dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('#cancel-reset').onclick=()=>dialog.close();dialog.querySelector('#confirm-reset').onclick=()=>{saved={};persist();dialog.close();render();toast('Demo workflow reset')};dialog.showModal()}
function exportCSV(){const rows=view==='queue'?workflowRows().filter(a=>signals(a).motion!=='Monitor'):view==='renewals'?accounts.filter(a=>a.renewalDays<=90):view==='quality'?accounts.filter(a=>quality(a).length):filtered(accounts,filters);const csv=accountCSV(rows,saved);const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));dialog.innerHTML=`<div class="dialog-top"><h2 id="detail-title">Export ${rows.length} accounts</h2><button class="close" aria-label="Close export">×</button></div><div class="dialog-body"><p>Your export contains the current view and filters, with locally assigned owners and progress. Every row is labeled synthetic.</p><label for="csv-preview" style="display:block;margin-top:18px">CSV preview</label><textarea id="csv-preview" class="field note" readonly style="height:240px">${escape(csv)}</textarea><a class="btn primary" id="download-csv" href="${url}" download="revenue-signal-lab-synthetic-accounts.csv">Download CSV</a><p class="reason">If your browser blocks downloads, select and copy the preview above.</p></div>`;dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});dialog.showModal()}
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(v!==view){view=v;render()}});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_revenue_account',description:'Open a synthetic account detail panel using its account ID.',inputSchema:{type:'object',properties:{accountId:{type:'string'}},required:['accountId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.accountId!=='string'||Object.keys(input).some(k=>k!=='accountId'))throw new Error('Provide only accountId');openAccount(input.accountId);return {accountId:selected,opened:dialog.open}}})).catch(()=>{})}catch{}}
